import numpy as np
from gensim import matutils
from numpy import dot, array


class VectorUtil:
    IDF_TOTAL_NUM_DIVISOR = 1
    IDF_COUNT_DIVISOR = 1

    @staticmethod
    def similarity(vector_1, vector_2):
        return dot(VectorUtil._unitvec(vector_1), VectorUtil._unitvec(vector_2))

    @staticmethod
    def cosine_similarities(vector_1, vectors_all):
        norm = VectorUtil._compute_norm(vector_1)
        all_norms = VectorUtil._compute_norms(vectors_all)
        dot_products = VectorUtil._compute_dot_products(vectors_all, vector_1)
        return VectorUtil._compute_similarities(dot_products, norm, all_norms)

    @staticmethod
    def n_similarity(vector_list_1, vector_list_2):
        VectorUtil._validate_vector_lists(vector_list_1, vector_list_2)
        mean_1 = VectorUtil._compute_mean(vector_list_1)
        mean_2 = VectorUtil._compute_mean(vector_list_2)
        return dot(VectorUtil._unitvec(mean_1), VectorUtil._unitvec(mean_2))

    @staticmethod
    def compute_idf_weight_dict(total_num, number_dict):
        index_2_key_map = VectorUtil._build_index_to_key_map(number_dict)
        count_array = VectorUtil._build_count_array(number_dict)
        idf_weights = VectorUtil._compute_idf_weights(total_num, count_array)
        return VectorUtil._build_weight_dict(idf_weights, index_2_key_map)

    @staticmethod
    def _unitvec(vector):
        return matutils.unitvec(vector)

    @staticmethod
    def _compute_norm(vector):
        return np.linalg.norm(vector)

    @staticmethod
    def _compute_norms(vectors):
        return np.linalg.norm(vectors, axis=1)

    @staticmethod
    def _compute_dot_products(vectors_all, vector_1):
        return dot(vectors_all, vector_1)

    @staticmethod
    def _compute_similarities(dot_products, norm, all_norms):
        return dot_products / (norm * all_norms)

    @staticmethod
    def _validate_vector_lists(vector_list_1, vector_list_2):
        if not (len(vector_list_1) and len(vector_list_2)):
            raise ZeroDivisionError('At least one of the passed list is empty.')

    @staticmethod
    def _compute_mean(vector_list):
        return array(vector_list).mean(axis=0)

    @staticmethod
    def _build_index_to_key_map(number_dict):
        index_to_key_map = {}
        for index, key in enumerate(number_dict.keys()):
            index_to_key_map[index] = key
        return index_to_key_map

    @staticmethod
    def _build_count_array(number_dict):
        return np.array(list(number_dict.values()))

    @staticmethod
    def _compute_idf_weights(total_num, count_array):
        return np.log((total_num + VectorUtil.IDF_TOTAL_NUM_DIVISOR) / 
                      (count_array + VectorUtil.IDF_COUNT_DIVISOR))

    @staticmethod
    def _build_weight_dict(idf_weights, index_2_key_map):
        return {key: idf_weights[index] for index, key in index_2_key_map.items()}
